package com.friendoncampus.order.web;
import java.util.UUID;import org.springframework.beans.factory.ObjectProvider;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import com.friendoncampus.order.service.OrderEvidenceExportService;
@RestController
public class OrderEvidenceController {private final ObjectProvider<JdbcClient> databases;public OrderEvidenceController(ObjectProvider<JdbcClient> databases){this.databases=databases;}@GetMapping({"/internal/orders/orders/{orderId}/evidence","/internal/orders/{orderId}/evidence"})public ResponseEntity<OrderEvidenceExportService.Export> evidence(@PathVariable UUID orderId,@RequestParam(required=false)String cursor,@RequestParam(defaultValue="100")int limit){JdbcClient database=databases.getIfAvailable();if(database==null)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Order evidence storage is unavailable");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new OrderEvidenceExportService(database).read(orderId,cursor,limit));}}
